#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    long long maxCappedSum(std::vector<int>& nums, int k, int cap) {
        std::vector<int> capped;
        capped.reserve(nums.size());
        for (int x : nums) capped.push_back(std::min(x, cap));
        std::sort(capped.begin(), capped.end(), std::greater<int>());

        long long total = 0;
        int take = std::min((int)capped.size(), k);
        for (int i = 0; i < take; ++i) total += capped[i];
        return total;
    }
};

import java.util.*;

class Solution {
    public long maxCappedSum(int[] nums, int k, int cap) {
        int n = nums.length;
        int[] capped = new int[n];
        for (int i = 0; i < n; i++) capped[i] = Math.min(nums[i], cap);
        Arrays.sort(capped);

        long total = 0;
        for (int i = n - 1; i >= Math.max(0, n - k); i--) {
            total += capped[i];
        }
        return total;
    }
}

var maxCappedSum = function(nums, k, cap) {
    const capped = nums.map(x => Math.min(x, cap)).sort((a, b) => b - a);
    let total = 0;
    const take = Math.min(capped.length, k);
    for (let i = 0; i < take; i++) total += capped[i];
    return total;
};
